/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type ClosePollInput = {
  baseSha: string;
  /**
   * What the closer decided. A question left out gets what the votes came to;
   * one given with no picks and no answer in other words is left undecided. A
   * tied question must be given.
   */
  decisions?: Array<PollAnswerInput>;
  note?: string | null | undefined;
  poll: string | number;
};

/**
 * What to change on an open poll; a field left out is left as it is, and a
 * null `results` or `deadline` removes it.
 */
export type EditPollInput = {
  baseSha: string;
  deadline?: string | null | undefined;
  poll: string | number;
  preamble?: string | null | undefined;
  /** Replaces every question; revokes every ballot unless they come out the same. */
  questions?: Array<PollQuestionInput> | null | undefined;
  results?: PollResults | null | undefined;
  title?: string | null | undefined;
};

export type OpenPollInput = {
  deadline?: string | null | undefined;
  /** The issue's ID or an unambiguous prefix; it must be open. */
  issue: string | number;
  preamble?: string | null | undefined;
  questions: Array<PollQuestionInput>;
  results?: PollResults | null | undefined;
  title: string;
};

export type PollAnswerInput = {
  other?: string | null | undefined;
  picks?: Array<string>;
  question: string;
};

/** What became of a vote (`doc/spec.md` §6.1). */
export type PollBallotState =
  | 'COUNTED'
  /** A file with faults: not read at all. */
  | 'INVALID'
  /** Cast after the poll was closed: not counted. */
  | 'LATE'
  | 'REVOKED'
  /** An earlier vote of somebody who voted again. */
  | 'SUPERSEDED'
  | 'WITHDRAWN';

export type PollOptionInput = {
  /** Markdown. */
  description?: string | null | undefined;
  /** A slug; made from the label when absent. */
  id?: string | null | undefined;
  /** One line. */
  label: string;
};

export type PollQuestionInput = {
  /** A slug; q1, q2… by position when absent. */
  id?: string | null | undefined;
  multi?: boolean | null | undefined;
  options: Array<PollOptionInput>;
  other?: boolean | null | undefined;
  /** One line. */
  text: string;
};

/** When a front end shows the tallies (`doc/spec.md` §6.4). The API always carries them. */
export type PollResults =
  /** Once the person looking has a ballot that counts, or the poll is closed. */
  | 'HIDDEN'
  | 'VISIBLE';

/** Open, or closed — by somebody, or because its issue is (`doc/spec.md` §6.2). */
export type PollStatus =
  | 'CLOSED'
  | 'OPEN';

/** Where somebody stands on a poll: their ballot's state, or NONE. */
export type PollVoterState =
  | 'COUNTED'
  | 'NONE'
  /** The questions changed since they voted: asked again. */
  | 'REVOKED'
  | 'WITHDRAWN';

export type ReopenPollInput = {
  baseSha: string;
  poll: string | number;
};

/** Issues are open or closed; pull requests may also be merged (spec 02 §2.1). */
export type Status =
  | 'CLOSED'
  | 'MERGED'
  | 'OPEN';

export type VotePollInput = {
  /** A question left out, or answered with nothing, is skipped. None at all withdraws. */
  answers: Array<PollAnswerInput>;
  /**
   * The poll's `fingerprint` when the form was built: a vote against questions
   * that have changed since is refused with STALE_CONTENT.
   */
  fingerprint: string;
  /** Why, in Markdown. Left out, the viewer's last note is kept; an empty one removes it. */
  note?: string | null | undefined;
  poll: string | number;
};

